module logic;
use model {Summary};
use util {reverse};
fn run(data:Bytes,limit:I64)->Summary {
 let parsed=while(state:Summary=Summary {frames:List::empty<Bytes>(),consumed:0,error:0}; state.error==0 && state.consumed<Bytes::length(data)) {
  let start=state.consumed;
  let count=Bytes::at(data,start);
  if count>limit {
   Summary {...state,error:3}
  } else {
   if Bytes::length(data)-start<count+2 {
    Summary {...state,error:1}
   } else {
    let checksum=fold(i in count,total:I64=0) {
     (total+Bytes::at(data,start+1+i))%256
    };
    if checksum!=Bytes::at(data,start+1+count) {
     Summary {...state,error:2}
    } else {
     Summary {frames:List::prepend(Bytes::slice(data,start+1,count),state.frames),consumed:start+count+2,error:0}
    }
   }
  }
 };
 Summary {...parsed,frames:reverse(parsed.frames)}
}
